{
  "query": "mutation($username: String!, $title: String!) { createTaskList(username: $username, title: $title) { id username title creationDate } }",
  "variables": {
    "username": "MaxMustermann",
    "title": "Shopping List"
  }
}

{
  "query": "mutation($username: String!, $title: String!, $tasks: [TaskInput!]!) { createTaskListWithTasks(username: $username, title: $title, tasks: $tasks) { id username title creationDate tasks { id title taskDescription completed creationDate dueDate completionDate } } }",
  "variables": {
    "username": "MaxMustermann",
    "title": "Weekend Projects",
    "tasks": [
      {
        "username": "MaxMustermann",
        "title": "Build a Bookshelf",
        "taskDescription": "Assemble and paint a new bookshelf for the living room.",
        "completed": false,
        "dueDate": "2025-01-14"
      },
      {
        "username": "MaxMustermann",
        "title": "Fix the Garden Fence",
        "taskDescription": "Replace the broken panels on the fence.",
        "completed": false,
        "dueDate": "2025-01-20"
      }
    ]
  }
}

{
  "query": "query($username: String!) { getTaskListsSortedByTaskCountAsc(username: $username) { id username title creationDate tasks { id title taskDescription completed creationDate dueDate completionDate } } }",
  "variables": {
    "username": "MaxMustermann"
  }
}

{
  "query": "query($username: String!) { getTaskListsSortedByTaskCountDesc(username: $username) { id username title creationDate tasks { id title taskDescription completed creationDate dueDate completionDate } } }",
  "variables": {
    "username": "MaxMustermann"
  }
}

{
  "query": "query($username: String!) { getTaskListsSortedByCreationDateAsc(username: $username) { id username title creationDate tasks { id title taskDescription completed creationDate dueDate completionDate } } }",
  "variables": {
    "username": "MaxMustermann"
  }
}

{
  "query": "query($username: String!) { getTaskListsSortedByCreationDateDesc(username: $username) { id username title creationDate tasks { id title taskDescription completed creationDate dueDate completionDate } } }",
  "variables": {
    "username": "MaxMustermann"
  }
}

{
  "query": "query($id: ID!) { getTaskListById(id: $id) { id username title creationDate tasks { id title taskDescription completed creationDate dueDate completionDate } } }",
  "variables": {
    "id": "77"
  }
}

{
  "query": "mutation($taskListId: ID!, $username: String!, $creationDate: String!, $tasks: [TaskInput!]!) { updateTaskList(taskListId: $taskListId, username: $username, creationDate: $creationDate, tasks: $tasks) { id username title creationDate tasks { id title taskDescription completed creationDate dueDate completionDate } } }",
  "variables": {
    "taskListId": "3",
    "username": "MaxMustermann",
    "creationDate": "2025-01-01",
    "title":"hALLOOO",
    "tasks": [

    ]
  }
}

{
  "query": "mutation($taskListId: ID!, $tasks: [TaskInput!]!) { addTasksToTaskList(taskListId: $taskListId, tasks: $tasks) { id username title creationDate tasks { id title taskDescription completed creationDate dueDate completionDate } } }",
  "variables": {
    "taskListId": "1",
    "tasks": [
      {
        "username": "MaxMustermann",
        "title": "Organize Closet",
        "taskDescription": "Sort clothes and donate unused items.",
        "completed": false,
        "dueDate": "2025-01-25"
      }
    ]
  }
}
